/*
 * Local Vue SFC highlighter for plain <pre class="vue"><code>...</code></pre> blocks.
 * No CDN dependency. It only enhances un-tokenized Vue blocks generated by Markdown/Pandoc.
 */
(function(){
  function escapeHtml(s){
    return s.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
  }
  function highlightLine(line){
    var html = escapeHtml(line);

    // Vue / HTML comments
    html = html.replace(/(&lt;!--[\s\S]*?--&gt;)/g, '<span class="vh-comment">$1</span>');

    // SFC block tags first
    html = html.replace(/(&lt;\/?)(template|script|style)(\s+setup|\s+scoped)?(\s*)(&gt;)/g,
      function(_, open, name, flag, sp, close){
        return '<span class="vh-punc">' + open + '</span><span class="vh-block">' + name + '</span>' +
          (flag ? '<span class="vh-attr">' + flag + '</span>' : '') + sp + '<span class="vh-punc">' + close + '</span>';
      }
    );

    // HTML / component tags
    html = html.replace(/(&lt;\/?)([A-Za-z][\w:-]*)([^&]*?)(&gt;)/g,
      function(_, open, tag, rest, close){
        var r = rest.replace(/([:@#A-Za-z_][\w:.-]*)(=)(&quot;.*?&quot;|'.*?'|[^\s&]+)?/g,
          function(__, attr, eq, val){
            return '<span class="vh-attr">' + attr + '</span><span class="vh-op">' + eq + '</span>' +
              (val ? '<span class="vh-string">' + val + '</span>' : '');
          }
        );
        return '<span class="vh-punc">' + open + '</span><span class="vh-tag">' + tag + '</span>' + r + '<span class="vh-punc">' + close + '</span>';
      }
    );

    // Vue interpolation
    html = html.replace(/(\{\{)(.*?)(\}\})/g, '<span class="vh-punc">$1</span><span class="vh-expr">$2</span><span class="vh-punc">$3</span>');

    // JS keywords in script blocks / expressions (simple enhancement)
    html = html.replace(/\b(const|let|var|return|import|from|export|default|function|computed|reactive|ref|createApp)\b/g,
      '<span class="vh-keyword">$1</span>');
    html = html.replace(/(&quot;.*?&quot;|'.*?'|`.*?`)/g, '<span class="vh-string">$1</span>');
    html = html.replace(/\b(\d+(?:\.\d+)?)\b/g, '<span class="vh-number">$1</span>');
    return html;
  }
  function highlightBlock(code){
    if(code.dataset.vueHighlighted === '1') return;
    var text = code.textContent || '';
    code.innerHTML = text.split(/\r?\n/).map(highlightLine).join('\n');
    code.dataset.vueHighlighted = '1';
    code.classList.add('vue-sfc-highlighted');
  }
  function run(){
    document.querySelectorAll('pre.vue code, pre code.vue, pre[class*="vue"] code').forEach(highlightBlock);
  }
  if(document.readyState === 'loading') document.addEventListener('DOMContentLoaded', run);
  else run();
})();